using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evals;

public class ChatEvals : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _builder = null!;
    private DistributedApplication _app = null!;
    private IChatClient _chatClient = null!;

    public async Task InitializeAsync()
    {
        _builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _builder.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
    }

    public async Task DisposeAsync()
    {
        await _app.DisposeAsync();
    }

    [Fact]
    public async Task Chat_responds_relevantly_to_greeting()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.NotNull(response);
        Assert.NotEmpty(response.Text);
    }

    [Fact]
    public async Task Chat_follows_instructions()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Always respond in exactly one sentence."),
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.NotNull(response);
        Assert.Contains("Paris", response.Text, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task Chat_response_is_coherent()
    {
        var evaluator = new CoherenceEvaluator();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what photosynthesis is in simple terms.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var turn = new ConversationTurn(messages, response.Messages);

        var results = await evaluator.EvaluateAsync(turn, _chatClient);

        Assert.All(results, r => Assert.True(
            r.Rating >= EvaluationRating.Average,
            $"Evaluator '{r.Metric.Name}' rated below average: {r.Rating}"));
    }

    [Fact]
    public async Task Chat_response_is_relevant()
    {
        var evaluator = new RelevanceEvaluator();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are three benefits of exercise?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var turn = new ConversationTurn(messages, response.Messages);

        var results = await evaluator.EvaluateAsync(turn, _chatClient);

        Assert.All(results, r => Assert.True(
            r.Rating >= EvaluationRating.Average,
            $"Evaluator '{r.Metric.Name}' rated below average: {r.Rating}"));
    }
}

